"""Generate the public report from measured capabilities and heavy-route evidence."""

import argparse
from collections import defaultdict
import json
from pathlib import Path
import statistics


def render(capabilities: dict, evidence: dict) -> str:
    if capabilities["generated_at"] != evidence["generated_at"]:
        raise ValueError(
            "Capabilities and heavy-route evidence are from different runs; rerun just bench-heavy"
        )
    lines = [
        "# Conversion benchmark report",
        "",
        "Generated by `just bench-report` from [capabilities](../crates/ariad-core/data/capabilities.json) "
        "and [route measurements](../bench/results/heavy-routes.json). "
        "See [the methodology](bench.md) for definitions, formulas and limitations.",
        "",
        f"Measured: {capabilities['generated_at']}. Cold repetitions per fixture: {evidence['repeat']}.",
        "",
        "## Measured engine edges",
        "",
        "Heavy adapter latency is median milliseconds per source page; base-suite edges report "
        "milliseconds per fixture. Memory is peak process-tree MiB. "
        "Null edges remain unmeasured. Scores describe the small authored corpus, not arbitrary documents.",
        "",
        "| Input | Output | Engine | Fidelity | Editability | p50 ms | Peak MiB | Samples |",
        "|---|---|---|---:|---:|---:|---:|---:|",
    ]
    for edge in capabilities["edges"]:
        metrics = edge["metrics"]
        if metrics is not None:
            values = [
                f"`{edge['from']}`",
                f"`{edge['to']}`",
                edge["engine"],
                f"{metrics['fidelity']:.3f}",
                f"{metrics['editability']:.3f}",
                f"{metrics['p50_ms']:.0f}",
                f"{metrics['peak_mem_mb']:.0f}",
                str(metrics["samples"]),
            ]
            lines.append("| " + " | ".join(values) + " |")
    lines += [
        "",
        "## Complete routes and PDF output",
        "",
        "Times below cover the complete cold pipeline for route rows. Edge rows cover only "
        "the named adapter. Read-back and SSIM computation are excluded from timing. "
        "Faithful-profile SSIM compares 96 dpi PDFium renders with independent authored PDF pages; "
        "missing pages score zero. DOCX is rendered through LibreOffice and Markdown through the native reader "
        "and Typst, outside measured time and memory; these renderer choices affect SSIM. Writers share their PDF artifact across semantic and visual scoring "
        "because they expose no separate profile-dependent rendering mode.",
        "",
        "| Input | Output | Engine | OCR | Scope | Fixtures | CER | Heading TED | TEDS | Fidelity | Editability | p50 ms | Peak MiB | SSIM |",
        "|---|---|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
    ]
    groups = defaultdict(list)
    for sample in evidence["samples"]:
        groups[
            (
                sample["source"],
                sample["target"],
                sample["engine"],
                sample["ocr"],
                sample["route"],
            )
        ].append(sample)
    for key, samples in sorted(groups.items()):
        source, target, engine, ocr, route = key

        def average(name):
            values = [
                sample[name] for sample in samples if sample.get(name) is not None
            ]
            return f"{statistics.fmean(values):.3f}" if values else "—"

        values = [
            source,
            target,
            engine,
            ocr,
            "route" if route else "edge",
            str(len(samples)),
            *(
                average(name)
                for name in (
                    "text_cer",
                    "heading_ted",
                    "teds",
                    "fidelity",
                    "editability",
                )
            ),
            f"{statistics.median(s['wall_ms'] for s in samples):.0f}",
            f"{max(s['peak_rss_bytes'] for s in samples) / 1048576:.0f}",
            average("ssim"),
        ]
        lines.append("| " + " | ".join(values) + " |")
    lines += [
        "",
        "## Interpretation and limits",
        "",
        "The Rust PDF reader extracts digital text with low startup cost. Docling reconstructs "
        "headings and tables and performs OCR; its cold model startup is included. RapidOCR's "
        "Vietnamese accuracy must be read separately from Tesseract. Neither backend is assigned "
        "another backend's measurements.",
        "",
        "The measured format graph selects Docling for editable PDF routes and the Rust reader "
        "for fast routes. File-based conversion and plan previews retain content-aware reader "
        "selection: digital text uses the built-in reader, scans require Docling, and an explicit "
        "`--engine docling` requests digital layout extraction.",
        "",
        "LibreOffice renders only the user's own Office or ODF file; the planner never chains it "
        "after another engine. Markdown, HTML, EPUB and IR JSON therefore write PDF through Typst "
        "in every profile, and the `md` to `pdf` LibreOffice route row is a comparison only.",
        "",
        "PDF read-back uses the Rust reader, so PDF writer structural scores include that reader's "
        "limitations. The authored reference uses two columns; reflowed Typst, slides and spreadsheet "
        "PDFs deliberately differ in layout, so SSIM is not a cross-format accuracy ranking. "
        "Extraction uses Docling's native HTML export parsed by Pandoc as the hypothesis; the Rust "
        "mapper is separately compared with that Docling source interpretation. Complete route scores "
        "compare final output directly with authored truth. The HTML bridge preserves table header flags and cell spans.",
        "",
        "## Environment",
        "",
    ]
    environment = evidence.get("environment", {})
    if environment:
        lines += [
            f"Host: {environment['platform']} {environment['architecture']}, "
            f"{environment['cpu_count']} logical CPUs; benchmark Python {environment['python']}.",
            "",
            "Timing depends on host load. Use the scheduled benchmark artifacts to compare runs "
            "on the same runner class; fidelity metrics remain independent of conversion timing.",
            "",
        ]
    if pack := evidence.get("pack"):
        lines += [
            f"Runtime: {pack['name']} {pack['version']}, manifest SHA-256 "
            f"`{pack['manifest_sha256']}`. Component hashes are preserved in the route evidence.",
            "",
        ]
    for name, version in sorted(evidence.get("tools", {}).items()):
        lines.append(f"- {name}: `{version}`.")
    return "\n".join(lines) + "\n"


def build_parser(parser: argparse.ArgumentParser):
    parser.add_argument(
        "--capabilities",
        type=Path,
        default=Path("crates/ariad-core/data/capabilities.json"),
    )
    parser.add_argument(
        "--evidence", type=Path, default=Path("bench/results/heavy-routes.json")
    )
    parser.add_argument("--out", type=Path, default=Path("docs/bench-report.md"))
    parser.add_argument("--check", action="store_true")


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    build_parser(parser)
    args = parser.parse_args(argv)
    report = render(
        json.loads(args.capabilities.read_text(encoding="utf-8")),
        json.loads(args.evidence.read_text(encoding="utf-8")),
    )
    if args.check:
        if args.out.read_text(encoding="utf-8") != report:
            parser.exit(1, "Benchmark report is stale; run just bench-report\n")
    else:
        args.out.write_text(report, encoding="utf-8")
    return 0
